// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    // A simple callee that mimics an ERC20-like transferFrom signature and always succeeds.
    // We deploy it to ensure the call from C actually goes to a contract (not an EOA),
    // but it will accept the call and return successfully so transfer completes.
    Callee callee;

    function setUp() public { 
        c = new airPort();
        callee = new Callee();
    }

    // fuzz the from address (as uint160), the to address (as uint160), and the value
    // We pass an array of exactly one recipient to avoid needing accumulation logic in the helper
    function testFuzz_property(uint160 fromRaw, uint160 toRaw, uint256 v) public {
        address from = address(uint160(fromRaw));
        address to = address(uint160(toRaw));

        // keep addresses non-zero to be in a sensible domain
        vm.assume(from != address(0));
        vm.assume(to != address(0));

        address[] memory tos = new address[](1);
        tos[0] = to;

        // Call and capture whether it completed (did not revert) and its return value
        bool completed;
        bool ret;
        // Use low-level call to capture the boolean return value of transfer
        // since solidity external call will revert on false returns when expecting a bool, we do abi.encodeWithSelector

        try c.transfer(from, address(callee), tos, v) returns (bool r) {
            completed = true;
            ret = r;
        } catch {
            completed = false;
            ret = false;
        }

        // GENERAL RULE (single assertion): If the call completed (did not revert), the reference implementation
        // returns true. We assert that `ret == true` whenever completed is true. The reference C satisfies this
        // for all inputs; the mutant (which returns false at the end) will cause this assertion to fail for some inputs
        // where the external calls succeed and thus the call completes.
        if (completed) {
            assertTrue(ret);
        } else {
            // If it reverted, we do not assert anything about ret; keep domain wide.
            assertTrue(true);
        }
    }
}

contract Callee {
    // match the selector: transferFrom(address,address,uint256)
    event Called(address from, address to, uint256 v);

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
